def parse_grid_from_file(path):
    with open(path, 'r') as f:
        content = f.read()
    # Try different formats
    formats = [
        lambda t: json.loads(t) if t.startswith('{') else None,
        lambda t: t.strip().split('\n') if any(x.isdigit() for x in t) else None,
    ]

    for fmt in formats:
        result = fmt(content)
        if result:
            if isinstance(result, list) and len(result) > 0 and all(isinstance(r, list) for r in result):
